
from pathlib import Path
import pandas as pd

# Locate project files regardless of where Python runs
PROJECT = Path(__file__).resolve().parent.parent
DATA = PROJECT / "data"

# Load data generated by our C++ engine
trades = pd.read_csv(DATA / "trades.csv")
liquidity = pd.read_csv(DATA / "liquidity.csv")

print("\n===== MARKET RISK INTELLIGENCE =====")

market = liquidity.iloc[0]

bid = market["best_bid_cents"] / 100
ask = market["best_ask_cents"] / 100
bid_depth = market["bid_depth"]
ask_depth = market["ask_depth"]
imbalance = market["imbalance"]

# Calculate market spread
midpoint = (bid + ask) / 2

if midpoint > 0:
    spread = (ask - bid) / midpoint * 100
else:
    spread = None

print(f"Best Bid: ${bid:.2f}")
print(f"Best Ask: ${ask:.2f}")
print(f"Bid Depth: {bid_depth}")
print(f"Ask Depth: {ask_depth}")
print(f"Order Book Imbalance: {imbalance:.2f}")

if spread is not None:
    print(f"Bid-Ask Spread: {spread:.2f}%")

# Investor-facing risk classification
print("\n===== INVESTOR RISK ALERTS =====")

if spread is None:
    print("SPREAD UNAVAILABLE: Both sides of the book are needed.")
elif spread > 1.0:
    print("HIGH SPREAD RISK: Immediate trading may be costly.")
elif spread > 0.3:
    print("MODERATE SPREAD RISK: Consider execution costs.")
else:
    print("LOW SPREAD RISK: Relatively tight quoted spread.")

if imbalance < -0.3:
    print("SELL-SIDE DEPTH DOMINANCE: More shares are offered for sale.")
elif imbalance > 0.3:
    print("BUY-SIDE DEPTH DOMINANCE: More shares are bid for.")
else:
    print("BALANCED ORDER BOOK: Similar displayed depth on both sides.")

# Trading activity
print("\n===== EXECUTION STATISTICS =====")

print(f"Number of trades: {len(trades)}")
print(f"Shares executed: {trades['quantity'].sum()}")

if not trades.empty:
    volume = trades["quantity"].sum()
    vwap = (
        (trades["price_cents"] * trades["quantity"]).sum()
        / volume / 100
    )

    print(f"Volume-Weighted Average Price: ${vwap:.2f}")

print("\nAnalysis completed successfully!")
